\set ON_ERROR_STOP on
\echo 'legacy-checkout-entitlement: migrated pending OTP grant regression'
begin;
create or replace function pg_temp.assert_true(ok boolean,message text) returns void language plpgsql as $$begin if ok is not true then raise exception 'assertion failed: %',message;end if;end$$;
select pg_temp.assert_true((select status='pending_otp' and payment_evidence_kind='legacy_post_payment' and payment_verified_at is null and payment_provider_session_id is null and payment_price_id is null from public.checkout_sessions where id='91000000-0000-0000-0000-000000000015'),'migration assigns only non-provider legacy evidence');
select pg_temp.assert_true((select disposition='reused_pending_otp' from public.reserve_checkout_intent('91000000-0000-0000-0000-000000000012','91000000-0000-0000-0000-000000000013','test','LEGACY-UPGRADE','legacy-upgrade@example.com','Legacy Upgrade','Legacy Upgrade LLC','Denver','pro','pending_payment',null,null,null,null)),'reservation recovers migrated pending OTP');
insert into auth.users(id,email) values('91000000-0000-0000-0000-000000000011','legacy-upgrade@example.com');
select public.grant_verified_website_entitlement('91000000-0000-0000-0000-000000000015','91000000-0000-0000-0000-000000000013','91000000-0000-0000-0000-000000000011');
select pg_temp.assert_true((select status='completed' and payment_evidence_kind='legacy_post_payment' and payment_verified_at is null from public.checkout_sessions where id='91000000-0000-0000-0000-000000000015'),'legacy pending OTP completes without fabricated verification');
select pg_temp.assert_true((select auth_user_id='91000000-0000-0000-0000-000000000011' from public.profiles where id='91000000-0000-0000-0000-000000000012'),'legacy owner linked atomically');
select pg_temp.assert_true((select state='active' and booking_admission=false and order_confirmed_at is null and purchased_at=(select created_at from public.checkout_sessions where id='91000000-0000-0000-0000-000000000015') from public.website_entitlements where checkout_session_id='91000000-0000-0000-0000-000000000015'),'legacy entitlement grants without charging enablement');
do $$begin begin update public.checkout_sessions set payment_evidence_kind='stripe_api' where id='91000000-0000-0000-0000-000000000015'; raise exception 'expected immutable legacy evidence rejection'; exception when sqlstate 'P0001' then if sqlerrm='expected immutable legacy evidence rejection' then raise; end if; end; end$$;
do $$begin begin insert into public.checkout_sessions(license_number,email,status,payment_evidence_kind,subscription_id,profile_id,website_id,environment,plan,context_json) values('FORGED','forged@example.com','pending_otp','legacy_post_payment','91000000-0000-0000-0000-000000000014','91000000-0000-0000-0000-000000000012','91000000-0000-0000-0000-000000000013','test','pro','{"websiteId":"91000000-0000-0000-0000-000000000013"}'); raise exception 'expected migration-only evidence rejection'; exception when sqlstate 'P0001' then if sqlerrm='expected migration-only evidence rejection' then raise; end if; end; end$$;
rollback;
